<script setup>
import {onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import BaseButton from '../../components/ui/BaseButton.vue'
import {permissionService} from '../../services/permissionService'
const route=useRoute(),router=useRouter(),isEdit=!!route.params.id,loading=ref(false),saving=ref(false),errorMessage=ref('')
const form=reactive({name:'',codename:'',content_type:''})
async function load(){if(!isEdit)return;loading.value=true;try{const res=await permissionService.get(route.params.id),row=res?.data||res;form.name=row.name||'';form.codename=row.codename||'';form.content_type=row.content_type||''}catch(e){errorMessage.value=e?.message||'Unable to load permission.'}finally{loading.value=false}}
async function save(){errorMessage.value='';if(!form.name.trim()||!form.codename.trim()||!form.content_type.trim()){errorMessage.value='Name, codename, and content type are required.';return}saving.value=true;try{const payload={name:form.name.trim(),codename:form.codename.trim(),content_type:form.content_type.trim()};if(isEdit)await permissionService.update(route.params.id,payload);else await permissionService.create(payload);router.push('/permissions')}catch(e){errorMessage.value=e?.message||'Unable to save permission.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><section class="module-page"><div class="module-page-intro"><div><h2>{{isEdit?'Edit Permission':'Create Permission'}}</h2><p class="module-description">Enter permission name, codename, and content type.</p></div><BaseButton variant="secondary" @click="router.push('/permissions')">← Back to permissions</BaseButton></div><section class="module-panel module-form-panel"><div class="module-panel-header"><h3>Permission information</h3></div><p v-if="loading" class="module-description" style="padding:16px 24px">Loading permission…</p><form v-else @submit.prevent="save"><div class="module-form-grid"><label class="module-form-field"><span>Name *</span><input v-model="form.name" class="ui-input" placeholder="Create Users" required /></label><label class="module-form-field"><span>Codename *</span><input v-model="form.codename" class="ui-input" placeholder="user_create" required /></label><label class="module-form-field"><span>Content type *</span><input v-model="form.content_type" class="ui-input" placeholder="User" required /></label></div><p v-if="errorMessage" role="alert" style="margin:0 24px 16px;color:#b43f4a">{{errorMessage}}</p><div class="module-form-footer"><span>Changes are sent to the permissions API.</span><div><BaseButton type="button" variant="secondary" @click="router.push('/permissions')">Cancel</BaseButton><BaseButton type="submit" :disabled="saving||loading">{{saving?'Saving…':isEdit?'Save changes':'Create permission'}}</BaseButton></div></div></form></section></section></template>
